<script setup lang="ts">import{ref}from"vue";const props=defineProps<{items:Array<{value:string;label:string;content:string}>;defaultValue?:string}>();const active=ref(props.defaultValue||props.items[0]?.value);</script><template><div class="acme-tabs"><div class="acme-tabs__list" role="tablist"><button v-for="item in items" :key="item.value" class="acme-tabs__trigger" role="tab" :aria-selected="active===item.value" @click="active=item.value">{{item.label}}</button></div><div v-for="item in items" v-show="active===item.value" :key="item.value" role="tabpanel" style="padding:1rem 0">{{item.content}}</div></div></template>